from datetime import datetime, timedelta
from functools import partial
from funcy import cache, reraise, SkipMemoization

calls = []
@cache(timedelta(seconds=60), key_func=lambda x: x)
def cached(x):
    calls.append(x)
    return x * 2

memory = cached.memory
assert isinstance(memory, dict) and not memory
assert cached.skip is SkipMemoization
assert cached(2) == cached(2) == 4
assert calls == [2]
assert memory[2][0] == 4 and isinstance(memory[2][1], datetime)
memory[2] = (9, datetime.now())
assert cached(2) == 9
cached.invalidate(2)
assert cached.memory is memory and memory == {}
cached(2)
cached.invalidate_all()
assert cached.memory is memory and memory == {}
cached(2)
memory.clear()
assert cached(2) == 4 and calls == [2, 2, 2, 2]

seen = []
def transform(error, prefix='new: '):
    seen.append(error)
    return RuntimeError(prefix + str(error))

@reraise([ValueError, KeyError], partial(transform, prefix='converted: '))
def fail(error):
    raise error

for original in (ValueError('one'), KeyError('two')):
    try:
        fail(original)
    except RuntimeError as raised:
        assert raised.__cause__ is original
        assert str(raised) == 'converted: ' + str(original)
assert len(seen) == 2

original = ValueError('context')
try:
    with reraise(ValueError, transform):
        raise original
except RuntimeError as raised:
    assert raised.__cause__ is original

class CallableError(Exception):
    def __call__(self, error):
        raise AssertionError('Exception instance should not be called')

for target in (RuntimeError, RuntimeError('fixed'), CallableError('callable')):
    try:
        with reraise(ValueError, target):
            raise original
    except (RuntimeError, CallableError) as raised:
        assert raised.__cause__ is original
        if not isinstance(target, type):
            assert raised is target
        else:
            assert raised.args == ()

with reraise(ValueError, transform):
    pass
try:
    with reraise(ValueError, transform):
        raise TypeError('unmatched')
except TypeError:
    pass
else:
    raise AssertionError('Unmatched exception was swallowed')
assert len(seen) == 3
print('Focused R2 and R3 checks passed')
